    primes = []
    for i in range(2, n + 1):
        if is_prime(i):
            primes.append(i)
    primes.sort(reverse=True)
    count = 0
    result = []
    for prime in primes:
        while n >= prime:
            n -= prime
            result.append(prime)
            count += 1
