class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.t = [0] * (n + 1)

    def add(self, i, delta):
        while i <= self.n:
            self.t[i] += delta
            i += i & -i

    def query(self, i):
        ans = 0
        while i > 0:
            ans += self.t[i]
            i -= i & -i
        return ans

class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.t = [0] * (4 * n)

    def update(self, i, val):
        i += self.n
        self.t[i] = val
        while i > 1:
            i >>= 1
            self.t[i] = max(self.t[2 * i], self.t[2 * i + 1])

    def query(self, l, r):
        l += self.n
        r += self.n
        ans = 0
        while l < r:
            if l & 1:
                ans = max(ans, self.t[l])
                l += 1
            if r & 1:
                r -= 1
                ans = max(ans, self.t[r])
            l >>= 1
            r >>= 1
        return ans

