class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.red = [0] * n
        self.blue = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, c):
        root_x = self.find(x)
        root_y = self.find(c)
        if root_x != root_y:
            if self.size[root_x] < self.size[root_y]:
                root_x, root_y = root_y, root_x
            self.parent[root_y] = root_x
            self.size[root_x] += self.size[root_y]
            if self.red[root_y]:
                self.blue[root_x] = 1
            elif self.blue[root_y]:
                self.red[root_x] = 1

    def is_red(self, x):
